pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund Alice with 2 ether
        address alice = address(0x1234);
        vm.deal(alice, 2 ether);

        // Alice locks in a guess: block.number starts at 0, so lockInGuess sets block = 1
        bytes32 guessHash = keccak256(abi.encodePacked(uint(1)));
        vm.prank(alice);
        c.lockInGuess{value: 1 ether}(guessHash);

        // Warp to block 2 so settle can execute
        vm.warp(2);
        vm.roll(2);

        // The answer is keccak256(blockhash(1)). blockhash(1) = keccak256(abi.encodePacked(uint(1))) for block #1? Not exactly, but we can compute it: blockhash(1) = hash of block 1, which we can set via vm.
        // To make the answer equal to guessHash, we need blockhash(1) to be such that keccak256(abi.encodePacked(blockhash(1))) == guessHash.
        // Since guessHash = keccak256(abi.encodePacked(uint(1))), we need blockhash(1) == uint(1).
        // Use vm.store to set blockhash for block 1 to bytes32(uint(1)).
        // For simplicity, we can override the blockhash via vm.roll and by mining? Actually, we can just set the blockhash by using a known block.
        // Simpler: we can make the answer equal guessHash by ensuring blockhash(1) == bytes32(uint(1)). But vm.roll doesn't set blockhash.
        // Instead, we can compute what blockhash would be if we mine a block. But we can use vm.etch? No.
        // Better: Use vm.store to set the blockhash directly? That's not allowed.
        // Alternative: Use a concrete block where blockhash(1) is known. In Foundry test, block 0 has hash zero. block 1 is not mined. We can use vm.warp and vm.roll but blockhash for non-existent blocks returns 0.
        // So let's adjust: blockhash(1) = 0x0, then answer = keccak256(abi.encodePacked(bytes32(0))) = 0x290decd9548b62a8d60345a988386fc84ba6bc95484008f6362f93160ef3e563.
        // We need guessHash to match that.
        // So we set guessHash = keccak256(abi.encodePacked(bytes32(0))).
        bytes32 correctHash = keccak256(abi.encodePacked(bytes32(0)));

        // Re-deploy for clean state
        c = new C();
        vm.deal(alice, 2 ether);
        vm.prank(alice);
        c.lockInGuess{value: 1 ether}(correctHash);

        // Warp to block 2
        vm.warp(2);
        vm.roll(2);

        uint256 balanceBefore = address(c).balance;
        vm.prank(alice);
        c.settle();
        uint256 balanceAfter = address(c).balance;

        // In reference, transfer occurs: balance decreases by 2 ether.
        // In bug, no transfer: balance unchanged.
        bool didTransfer = (balanceBefore - balanceAfter >= 2 ether);
        assertTrue(didTransfer, "Reference should transfer 2 ether when guess matches answer");
    }
}

