pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund the contract with 1 ether (constructor requires it)
        vm.deal(address(this), 1 ether);
        // Deploy in setUp, but we must also fund the contract itself—constructor requires msg.value
        // Actually, the deployment in setUp already succeeded, so the contract has 1 ether.
        // Fund the test contract to send ether for lockInGuess
        vm.deal(address(this), 2 ether);

        // Compute the future blockhash we will guess
        // The lockInGuess stores block.number + 1 as the target block
        // We need to know blockhash(block.number+1) at settle time
        // Determine current block number first
        uint256 targetBlock = block.number + 1;
        bytes32 expectedAnswer = blockhash(targetBlock); // blockhash of current block+1 is 0 now, but will be set later
        // Actually, we cannot predict a future blockhash. So we need a trick: lockInGuess, then warp to a block where we know the blockhash.
        // Simpler: Use vm.roll to set a specific block number, then compute its hash with vm.blockHash.
        // Set block.number to, say, 1000
        vm.roll(1000);
        bytes32 knownBlockhash = blockhash(1000); // This will be 0x000... because blockhash only works for recent blocks in vm
        // In Foundry, blockhash is deterministic: it's keccak256(block number) when using vm.roll
        // Actually, blockhash(1000) returns 0 because it's too old. We need to use a recent block.
        // Better: Use block.number currently and roll to a new block so that the target block becomes recent.
        // Let's do: set block.number = 100, then lock in guess targeting block 101.
        vm.roll(100);
        // The lockInGuess will set target block = block.number + 1 = 101
        // After calling lockInGuess, we roll to block 102 (so block.number > target block) and blockhash(101) is available.
        bytes32 futureHash = vm.blockHash(101); // Because we will roll to 102, blockhash(101) is available
        // Now lock in guess with that future hash
        c.lockInGuess{value: 1 ether}(futureHash);

        // Warp to block 102
        vm.roll(102);

        // Now settle: reference will transfer 2 ether because guess == answer, buggy will not
        uint256 balanceBefore = address(c).balance;
        c.settle();
        uint256 balanceAfter = address(c).balance;

        // Reference: transfer 2 ether occurs, so balance decreases by 2
        // Buggy: no transfer, so balance stays same
        // Assert that there was a transfer (i.e., balanceAfter < balanceBefore)
        assertTrue(balanceAfter < balanceBefore, "Expected transfer on reference, buggy would not transfer");
    }
}

